#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long pow_mod(long long base, int exp) {
    long long result = 1;
    long long cur = base;
    int e = exp;
    while (e > 0) {
        if (e & 1) {
            result = (result * cur) % MOD;
        }
        cur = (cur * cur) % MOD;
        e >>= 1;
    }
    return result;
}

vector<vector<long long>> multiply_matrices(const vector<vector<long long>>& a, const vector<vector<long long>>& b) {
    int rA = a.size(), cA = a[0].size();
    int rB = b.size(), cB = b[0].size();
    vector<vector<long long>> res(rA, vector<long long>(cB, 0));
    for (int i = 0; i < rA; i++) {
        for (int j = 0; j < cB; j++) {
            long long sum = 0;
            for (int k = 0; k < cA; k++) {
                sum += a[i][k] * b[k][j];
            }
            res[i][j] = sum % MOD;
        }
    }
    return res;
}

vector<vector<long long>> matrix_power(vector<vector<long long>> base, int exp) {
    if (exp == 1) return base;
    vector<vector<long long>> half = matrix_power(base, exp / 2);
    vector<vector<long long>> result = multiply_matrices(half, half);
    if (exp % 2 == 1) {
        result = multiply_matrices(result, base);
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, l, r;
    cin >> n >> m >> l >> r;

    if (n % 2 == 1 && m % 2 == 1) {
        long long res = pow_mod(pow_mod(r - l + 1, n), m);
        cout << res << "\n";
        return 0;
    }

    int evenCount = r / 2 - (l + 1) / 2 + 1;
    int oddCount = (r - l + 1) - evenCount;

    vector<vector<long long>> matrix = {{evenCount, oddCount}, {oddCount, evenCount}};
    matrix = matrix_power(matrix, n);
    matrix = matrix_power(matrix, m);
    cout << matrix[0][0] << "\n";

    return 0;
}
